<?php use App\Models\Ticket; ?>
<dialog id="ticket-edit-dialog" class="dialog ticket-edit-dialog" aria-labelledby="ticket-edit-title">
<header class="dialog-header"><h2 id="ticket-edit-title">Modifier <?= e($ticket['key']) ?></h2><button type="button" class="icon-button" data-close aria-label="Fermer"><?= icon('close') ?></button></header>
<form id="ticket-edit-form" method="post" action="/tickets/<?= (int)$ticket['id'] ?>" class="stack"><?= csrf() ?><input type="hidden" name="version" value="<?= (int)$ticket['version'] ?>"><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><label>Résumé<input name="title" value="<?= e($ticket['title']) ?>" required maxlength="240"></label><label>Avancement (%)<input type="number" name="progress_percent" min="0" max="100" step="1" value="<?= (int)$ticket['progress_percent'] ?>" required><small>De 0 à 100 %, indépendamment de l’état du ticket.</small></label><label>Temps total estimé (heures)<input name="estimated_hours" inputmode="decimal" value="<?= e($ticket['estimated_hours']) ?>" placeholder="Ex. : 2,5" maxlength="9"><small>Durée de travail prévue pour cette tâche. Facultatif, deux décimales maximum.</small></label><label>Description<textarea name="description" rows="9" placeholder="L’essentiel et les détails utiles…"><?= e($ticket['description']) ?></textarea></label><div class="inline-fields"><label>État<select name="status"><?php foreach(Ticket::STATUSES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['status']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label><label>Type<select name="type"><?php foreach(Ticket::TYPES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['type']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div><div class="inline-fields"><label>Personne assignée<select name="assignee_id"><option value="">Non assigné</option><?php foreach($members as $m): ?><option value="<?= (int)$m['id'] ?>" <?= $ticket['assignee_id']===$m['id']?'selected':'' ?>><?= e($m['name']) ?></option><?php endforeach; ?></select></label><label>Priorité<select name="priority"><?php foreach(Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['priority']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div><div class="inline-fields"><label>Date de début<input type="date" name="start_date" value="<?= e($ticket['start_date']) ?>"></label><label>Échéance<input type="date" name="due_date" value="<?= e($ticket['due_date']) ?>"></label></div><label>Parent<select name="parent_id"><option value="">Aucun</option><?php foreach($parents as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $ticket['parent_id']===$p['id']?'selected':'' ?>><?= e($project['project_key'].'-'.$p['number'].' · '.$p['title']) ?></option><?php endforeach; ?></select></label><?php $selectedTeam=$ticket['team_id']; require ROOT.'/app/Views/partials/ticket-team.php'; ?><label>Étiquettes<input name="labels" value="<?= e(implode(', ',$ticket['labels_array'])) ?>" placeholder="Séparées par une virgule"></label><label class="check-label"><input type="checkbox" name="flagged" value="1" <?= $ticket['flagged']?'checked':'' ?>>Ce ticket est bloqué</label><?php if($user['role']!=='viewer'): ?><button class="button primary">Enregistrer les modifications <?= icon('check') ?></button><?php endif; ?></form>
</dialog>
